INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('УПД Трейд Ресурс 12.10 МБТ в загрузку OData', 'УПД ООО «ВГ-ТРЕЙД» (Weissgauff) № 261012003/2 от 12.10.2026 по правилу «Создание файла для OData». Восемь колонок: Артикул (из «Код товара», текстом), Штрихкод (в УПД нет — пусто), Наименование (как в УПД), Количество, Цена с НДС, Страна, Номер ГТД, Номер РНПТ. 290 строк, 1 125 шт, 2 343 890,00 руб. — сходится с «Всего к оплате» и со счётом № 1178 до копейки. Все 267 номеров деклараций — в ГТД: у 9 вентиляторов поставщик заполнил графы прослеживаемости, но номер у них обычный ГТД из трёх частей без номера позиции, поэтому по решению владельца они тоже в ГТД; РНПТ пусто. В 23 строках номера нет в самом УПД (гладильные доски, дегидраторы, конвекторы, миксер), у 22 из них нет и страны.', '/converted/upd-treid-resurs-12-10-mbt-v-zagruzku-odata.xlsx', 'УПД Трейд Ресурс 12.10 МБТ в загрузку OData.xlsx', 'converted/upd-treid-resurs-12-10-mbt-v-zagruzku-odata.xlsx', 21486);